import{_ as s}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as t,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const y=JSON.parse('{"title":"Search syntax","description":"","frontmatter":{},"headers":[],"relativePath":"usage/search-syntax.md","filePath":"usage/search-syntax.md"}'),o={name:"usage/search-syntax.md"};function n(l,e,r,h,c,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="search-syntax" tabindex="-1">Search syntax <a class="header-anchor" href="#search-syntax" aria-label="Permalink to &quot;Search syntax&quot;">​</a></h1><p><code>github-code-search</code> automatically injects an <code>org:&lt;org&gt;</code> qualifier from <code>--org</code> and otherwise passes the rest of your query unchanged to the <a href="https://docs.github.com/en/search-github/searching-on-github/searching-code" target="_blank" rel="noreferrer">GitHub Code Search API</a>. Any syntax that works in the GitHub search bar also works here.</p><h2 id="basic-query" tabindex="-1">Basic query <a class="header-anchor" href="#basic-query" aria-label="Permalink to &quot;Basic query&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p>Searches for the literal string <code>useFeatureFlag</code> across all repositories in the <code>fulll</code> organisation.</p><h2 id="qualifiers" tabindex="-1">Qualifiers <a class="header-anchor" href="#qualifiers" aria-label="Permalink to &quot;Qualifiers&quot;">​</a></h2><p>GitHub code search supports a set of qualifiers you can combine with your keyword:</p><table tabindex="0"><thead><tr><th>Qualifier</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>language:&lt;lang&gt;</code></td><td>Filter by programming language</td><td><code>useFeatureFlag language:TypeScript</code></td></tr><tr><td><code>path:&lt;directory&gt;</code></td><td>Restrict to files located in a directory (or any of its subdirectories) — <strong>not</strong> a glob/extension filter</td><td><code>config path:src/config</code></td></tr><tr><td><code>filename:&lt;name&gt;</code></td><td>Match files by name (supports wildcards)</td><td><code>SECRET filename:.env</code></td></tr><tr><td><code>extension:&lt;ext&gt;</code></td><td>Match files by extension</td><td><code>connect extension:ts</code></td></tr><tr><td><code>repo:&lt;owner&gt;/&lt;repo&gt;</code></td><td>Restrict to a single repository (less useful here — use <code>--org</code>)</td><td><code>connect repo:fulll/service-b</code></td></tr><tr><td><code>NOT &lt;term&gt;</code></td><td>Exclude a keyword</td><td><code>connect NOT deprecated</code></td></tr><tr><td><code>&quot;exact phrase&quot;</code></td><td>Exact multi-word match</td><td><code>&quot;feature flag&quot;</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Qualifiers can be combined freely:<br><code>&quot;feature flag&quot; language:TypeScript path:src/</code></p></div><div class="warning custom-block"><p class="custom-block-title"><code>path:</code> does not support glob wildcards</p><p><code>path:</code> matches a <strong>directory location</strong>, not a filename pattern — GitHub&#39;s code search API silently ignores the <code>*</code> wildcard character rather than expanding it as a glob, so a query like <code>path:*.tf</code> matches few or no files. To filter by file type, use <code>language:&lt;lang&gt;</code> or <code>extension:&lt;ext&gt;</code> instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Wrong — path:*.tf is silently ignored by the GitHub API, returns no results</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;ACME123456789 path:*.tf&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Right — filters by language or extension instead</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;ACME123456789 language:hcl&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;ACME123456789 extension:tf&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p><code>github-code-search</code> detects this pattern and prints a warning on stderr when a <code>path:</code> qualifier contains a <code>*</code> character.</p></div><h2 id="practical-examples" tabindex="-1">Practical examples <a class="header-anchor" href="#practical-examples" aria-label="Permalink to &quot;Practical examples&quot;">​</a></h2><h3 id="find-all-usages-of-a-function" tabindex="-1">Find all usages of a function <a class="header-anchor" href="#find-all-usages-of-a-function" aria-label="Permalink to &quot;Find all usages of a function&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h3 id="restrict-to-typescript-files" tabindex="-1">Restrict to TypeScript files <a class="header-anchor" href="#restrict-to-typescript-files" aria-label="Permalink to &quot;Restrict to TypeScript files&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag language:TypeScript&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h3 id="search-in-a-specific-directory" tabindex="-1">Search in a specific directory <a class="header-anchor" href="#search-in-a-specific-directory" aria-label="Permalink to &quot;Search in a specific directory&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;SENTRY_DSN path:config&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h3 id="search-for-a-file-by-name" tabindex="-1">Search for a file by name <a class="header-anchor" href="#search-for-a-file-by-name" aria-label="Permalink to &quot;Search for a file by name&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;filename:docker-compose.yml&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h3 id="exclude-test-files" tabindex="-1">Exclude test files <a class="header-anchor" href="#exclude-test-files" aria-label="Permalink to &quot;Exclude test files&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag NOT filename:test NOT filename:spec&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h3 id="restrict-to-specific-repositories" tabindex="-1">Restrict to specific repositories <a class="header-anchor" href="#restrict-to-specific-repositories" aria-label="Permalink to &quot;Restrict to specific repositories&quot;">​</a></h3><p>Although <code>--org</code> already limits the search to your organisation, you can further narrow results to one or more specific repositories using <code>repo:</code> qualifiers in the query string:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag repo:fulll/service-b repo:fulll/service-a&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p><code>--org</code> is still required for the API call even when <code>repo:</code> qualifiers are present. The <code>org:&lt;org&gt;</code> qualifier is injected automatically alongside your query.</p><h3 id="find-hardcoded-secrets-audit-use-case" tabindex="-1">Find hardcoded secrets (audit use case) <a class="header-anchor" href="#find-hardcoded-secrets-audit-use-case" aria-label="Permalink to &quot;Find hardcoded secrets (audit use case)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;password= language:TypeScript NOT filename:test&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h2 id="regex-queries" tabindex="-1">Regex queries <a class="header-anchor" href="#regex-queries" aria-label="Permalink to &quot;Regex queries&quot;">​</a></h2><p><code>github-code-search</code> supports regex syntax using the <code>/pattern/flags</code> notation, just like the GitHub web UI.</p><p>Because the GitHub Code Search API does not natively support regex, the CLI automatically extracts a representative literal term from the regex to send to the API, then filters the returned results locally with the full pattern. In most cases this is fully transparent, including patterns that contain literal <code>&quot;</code> characters, which the CLI escapes automatically using GitHub&#39;s own quote-escaping syntax (see <a href="#searching-for-a-literal-quote-character">Searching for a literal quote character</a> below).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Imports using the axios module (any quote style)</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/from.*[&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;\\\`</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">]axios/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Axios dependency in package.json (any semver prefix) — the double quotes in</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># the pattern are preserved and escaped automatically for the GitHub API</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;/&quot;axios&quot;: &quot;[~^]?[0-9]&quot;/ filename:package.json&#39;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Old library require() calls</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/require</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">([&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">](old-lib)[&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">)/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Any of TODO, FIXME or HACK comments</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/TODO|FIXME|HACK/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Top-level alternation</p><p>When the regex contains a <strong>top-level <code>|</code></strong> (e.g. <code>TODO|FIXME|HACK</code>), the CLI sends an <code>A OR B OR C</code> query to the GitHub API so that <strong>all branches are covered</strong> — no results are missed.</p></div><h3 id="when-auto-extraction-is-not-precise-enough" tabindex="-1">When auto-extraction is not precise enough <a class="header-anchor" href="#when-auto-extraction-is-not-precise-enough" aria-label="Permalink to &quot;When auto-extraction is not precise enough&quot;">​</a></h3><p>If the extracted term is very short (fewer than 3 characters), the CLI will exit with a warning and ask you to provide a manual hint:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>⚠  Regex mode — No meaningful search term could be extracted from the regex pattern. Use --regex-hint &lt;term&gt; to specify the term to send to the GitHub API.</span></span></code></pre></div><p>This happens when the pattern has no literal characters at all, for example a pure version-number match:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;/[0-9]+\\.[0-9]+\\.[0-9]+/&#39;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p>Use <code>--regex-hint</code> to override the API search term while still applying the full regex filter locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;/[0-9]+\\.[0-9]+\\.[0-9]+/ filename:package.json&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --regex-hint</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Quoting a single word has no filtering effect</p><p>Wrapping a single word in double quotes (e.g. <code>--regex-hint &#39;&quot;axios&quot;&#39;</code>) does <strong>not</strong> narrow the GitHub search — GitHub treats a one-word quoted phrase exactly like the bare word. Quotes only matter for multi-word phrases (<code>&quot;feature flag&quot;</code>) or when you need to search for the literal <code>&quot;</code> character itself, see below.</p></div><div class="warning custom-block"><p class="custom-block-title">API coverage</p><p>The GitHub Code Search API returns <strong>at most 1,000 results</strong> per query. The regex filter is applied to those results; results beyond the API cap can never be seen. Refine the query with qualifiers (<code>language:</code>, <code>path:</code>, <code>filename:</code>) to keep the result set small.</p></div><h2 id="searching-for-a-literal-quote-character" tabindex="-1">Searching for a literal quote character <a class="header-anchor" href="#searching-for-a-literal-quote-character" aria-label="Permalink to &quot;Searching for a literal quote character&quot;">​</a></h2><p>GitHub&#39;s query syntax treats <code>&quot;</code> as a phrase delimiter, not a literal character. To search for an actual quote character (for example to match a <code>package.json</code> dependency key/value prefix like <code>&quot;react&quot;: &quot;</code>), escape it for <strong>both</strong> your shell and GitHub:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;&quot;\\&quot;react\\&quot;: \\&quot;&quot;&#39;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> myorg</span></span></code></pre></div><ul><li>The outer single quotes protect the whole argument from your shell.</li><li>The <code>\\&quot;</code> sequences are GitHub&#39;s own escape syntax for a literal quote character inside an exact phrase.</li></ul><p>If you instead pass raw, unescaped quotes, two things can happen:</p><ul><li><strong>An even number of quotes</strong> (e.g. <code>&quot;react&quot;: </code>) is valid GitHub syntax, but GitHub silently strips the quotes and treats the query as separate terms, so you get broader results than expected, not an error.</li><li><strong>An odd number of quotes</strong> (e.g. <code>&quot;react&quot;: &quot;</code>) is rejected by GitHub with an opaque <code>422 ERROR_TYPE_QUERY_PARSING_FATAL</code> error. <code>github-code-search</code> detects this locally and fails fast with an actionable message before ever calling the API:</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: Unbalanced double quotes in query: &quot;\\&quot;react\\&quot;: \\&quot;&quot;. GitHub rejects this with a query</span></span>
<span class="line"><span>parsing error. To search for a literal quote character, escape it for both your shell and</span></span>
<span class="line"><span>GitHub, e.g.: github-code-search &#39;&quot;\\&quot;react\\&quot;: \\&quot;&quot;&#39; --org myorg</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Shell escaping consumes backslashes too</p><p>Typing <code>&quot;\\&quot;react\\&quot;: \\&quot;&quot;</code> directly (double-quoted at the shell level) does <strong>not</strong> work: your shell resolves <code>\\&quot;</code> to a literal <code>&quot;</code> <em>before</em> the CLI ever sees it, so the program receives the same unbalanced <code>&quot;react&quot;: &quot;</code> string as if you had typed no backslashes at all. Always wrap the whole argument in <strong>single</strong> quotes so the backslashes reach GitHub unchanged, as in the example above.</p></div><h2 id="api-limits" tabindex="-1">API limits <a class="header-anchor" href="#api-limits" aria-label="Permalink to &quot;API limits&quot;">​</a></h2><p>The GitHub Code Search API returns at most <strong>1,000 results</strong> per query. If your query returns more, refine it with qualifiers (especially <code>language:</code> or <code>path:</code>) to stay below the limit.</p><p>See the <a href="/github-code-search/v2/reference/github-api-limits.html">GitHub API limits</a> reference for details on rate limits and pagination.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><p>Once you have results, use the <a href="/github-code-search/v2/usage/interactive-mode.html">interactive mode</a> to browse and select them, or the <a href="/github-code-search/v2/usage/non-interactive-mode.html">non-interactive mode</a> to pipe them into a script.</p>`,54)])])}const f=s(o,[["render",n]]);export{y as __pageData,f as default};
